// Verify the HMAC signature the FastAPI service sends, then flatten the
// payload into the shape the downstream nodes expect.
const crypto = require('crypto');
const SECRET = $env.N8N_WEBHOOK_SECRET || '';

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};

  if (SECRET) {
    const expected = crypto
      .createHmac('sha256', SECRET)
      .update(JSON.stringify(body))
      .digest('hex');
    if (headers['x-signature'] !== expected) {
      throw new Error('Invalid signature - rejecting lead ' + (body.lead_id ?? '?'));
    }
  }

  const transcript = (body.transcript || [])
    .map((m) => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  out.push({
    json: {
      lead_id: body.lead_id,
      conversation_id: body.conversation_id,
      name: body.name || '(not given)',
      email: body.email || '',
      phone: body.phone || '',
      intent: body.intent || 'unknown',
      lead_score: Number(body.lead_score || 0),
      priority: body.priority || 'warm',
      message: body.message || '',
      source_page: body.source_page || '',
      company: body.company || '',
      captured_at: body.captured_at || new Date().toISOString(),
      transcript,
    },
  });
}

return out;

